import * as Cloudflare from "@alchemy.run/cloudflare";
import { Stack } from "alchemy/Stack";
import * as Config from "effect/Config";
import * as Effect from "effect/Effect";
import { HttpServerRequest } from "effect/http/HttpServerRequest";
import * as HttpServerResponse from "effect/http/HttpServerResponse";
import { hostnameFor, siteDomainFor } from "./Hostnames.ts";

/** `apps/web`'s landing-page build output (`vite.site.config.ts`). Absolute, like MainWorker's assets. */
const assetsDirectory = new URL("../../../apps/web/dist-site", import.meta.url).pathname;

/**
 * The Site Worker: the static landing page (English at `/`, German at `/de/`), prerendered at build
 * time and served from assets. Its one dynamic route, `/app`, redirects to the app's origin, so the
 * app Worker's routing and auth stay untouched (ADR 0020).
 */
export default class SiteWorker extends Cloudflare.Worker<SiteWorker>()(
  "Site",
  Effect.gen(function* () {
    const stack = yield* Stack;
    const domain = siteDomainFor(stack.stage);
    const appHostname = hostnameFor(stack.stage, "app");
    return {
      main: import.meta.url,
      assets: {
        directory: assetsDirectory,
        htmlHandling: "auto-trailing-slash",
        runWorkerFirst: ["/app", "/app/"],
      },
      // Stages without a custom app hostname live on workers.dev, whose URL is not known here: `/app` falls back to `/`.
      env: {
        ...(appHostname === undefined ? {} : { APP_ORIGIN: `https://${appHostname}` }),
      },
      ...(domain === undefined ? {} : { domain }),
    };
  }),
  Effect.gen(function* () {
    const appOrigin = yield* Config.String("APP_ORIGIN").pipe(Config.withDefault("/"));

    return {
      fetch: Effect.gen(function* () {
        const request = yield* HttpServerRequest;
        const path = request.url.split("?")[0];
        if (request.method === "GET" && (path === "/app" || path === "/app/")) {
          return HttpServerResponse.redirect(appOrigin, { status: 302 });
        }
        return HttpServerResponse.empty({ status: 404 });
      }),
    };
  }),
) {}
import { assert, describe, it } from "@effect/vitest";
import { hostnameFor, siteDomainFor } from "./Hostnames.ts";

describe("hostnameFor (app and submit hostnames)", () => {
  it("serves production, staging and PR stages on their subdomains", () => {
    assert.strictEqual(hostnameFor("production", "app"), "app.surveybeat.app");
    assert.strictEqual(hostnameFor("staging", "submit"), "staging.submit.surveybeat.app");
    assert.strictEqual(hostnameFor("pr-12", "app"), "pr-12.app.surveybeat.app");
  });

  it("leaves personal stages on workers.dev", () => {
    assert.strictEqual(hostnameFor("dev-christoph", "app"), undefined);
  });
});

describe("siteDomainFor (landing page hostnames)", () => {
  it("serves staging and PR stages on one-level subdomains", () => {
    assert.strictEqual(siteDomainFor("staging"), "staging.surveybeat.app");
    assert.strictEqual(siteDomainFor("pr-12"), "pr-12.surveybeat.app");
  });

  it("keeps production on workers.dev until the apex cutover", () => {
    assert.strictEqual(siteDomainFor("production"), undefined);
  });

  it("serves the apex with www redirecting to it once the cutover is on", () => {
    assert.deepStrictEqual(siteDomainFor("production", true), {
      name: "surveybeat.app",
      redirects: ["www.surveybeat.app"],
    });
  });

  it("leaves personal stages on workers.dev", () => {
    assert.strictEqual(siteDomainFor("dev-christoph"), undefined);
    assert.strictEqual(siteDomainFor("dev-christoph", true), undefined);
  });
});

docs/adr/0004-minimum-group-size-per-aggregate.md:1:# The minimum group size applies per aggregate, never loosens for the past, and Release 1 has no live Results
docs/adr/0004-minimum-group-size-per-aggregate.md:3:Every number SurveyBeat shows is checked against the minimum group size (N) on its own Contributors: a Question counts the Submissions that answered it, and a Dimension score uses only Questions that meet N themselves, so a hidden Question cannot be recovered by subtraction. Each Round records the N it closed under and is always shown under the stricter of that and the current N. Raising N hides past Rounds, but lowering N never reveals a Round that members answered under a stricter promise. Release 1 shows no Results while a Round is Open, for Teams of any size, only the response count. This drops SPEC §5.3's live updates for Teams of 2N or more, which would let a Lead time a new response against a member who just said they answered.
SPEC.md:42:- Results showed for any number of responses. With two responses on a team of four, a lead can often guess who said what. The rebuild enforces a minimum group size before showing any result.
SPEC.md:142:- **Minimum group size.** No aggregate, comment, theme, or breakdown appears unless at least N people contributed to it. N defaults to 4. Admins can raise it but not set it below 3. The rule applies to every view, including filters and comparisons. A view that would fall below N shows "Not enough responses to protect anonymity" instead.
SPEC.md:148:- **Retention.** An organization sets a retention period for raw answers and comments, defaulting to 24 months. Aggregated results can be kept longer.
SPEC.md:157:- **Comparisons.** Leads of several teams, and leadership viewers, can compare teams on standard questions. The minimum group size applies to each team shown.
SPEC.md:238:- **Privacy tests are release blockers.** The suite proves at least the following. An anonymous submission has no stored path back to a person. Every result view respects the minimum group size, including subtraction across groups. Logs from the submission path contain no identifiers. Exports and the MCP server obey the same rules.
SPEC.md:249:Sign-in with AuthKit, plus organization and team setup by hand. Pulses from templates, with rating, choice, and text questions. Weekly cadence with time zones. Email invitations with one-tap first answers, and reminders. Anonymous mode with the minimum group size. Round results with trends and sample sizes. Actions with owner and status, shown in the next invitation. The full privacy test suite. Preview environments per pull request.
SPEC.md:274:1. Should members see raw comments, or only themes? Default is themes only, with the lead able to show raw comments if the minimum group size is met.
SPEC.md:275:2. What is the default minimum group size? Default is 4, with 3 as the floor.
54:2. **Short beats complete.** A pulse is 3 to 7 questions. The product pushes back when a lead adds more. A 90 percent response rate on five questions beats 40 percent on twenty.
119:- The pulse editor shows an estimated answer time, and warns when a pulse goes over 7 questions or about 90 seconds.
1:# Comments are redacted when stored, and the raw text is never kept
3:Release 1's rule-based redaction (ADR 0001) runs in the Submission Worker as the comment is saved. It uses the Organization's roster at that moment, and only the redacted text is stored. The raw text exists only in that request's memory. It is never logged, stored, or sent to a model. We rejected keeping the raw text and redacting each time a comment is shown, for two reasons. Deleting a Person would take their name out of the roster and expose it in every old comment that mentions them. And raw comments at rest would be the most identifying data SurveyBeat holds.
9:Each match becomes a placeholder (`[name]`, `[email]`, `[phone]`, `[handle]`, `[link]`). A comment is never held back as a whole. Roster names that are also ordinary words ("will", "may") are redacted anyway.
13:- Redaction is permanent. A false positive can't be undone, and a member who edits their comment edits the redacted text.
14:- People added to the roster later are not redacted from older comments.
141:- **Modes.** Each pulse picks one of three modes. Anonymous is the default. Attributed means the lead sees names. Confidential means the organization stores names for follow-up, but the lead sees only aggregates. Confidential needs an admin to turn it on, and the answer page must state it clearly.
123:- The first question can be answered directly from the message. In email, each rating value is a link that opens the answer page with that value chosen; the answer is saved when the member confirms it there, because email security scanners open every link (ADR 0007). In Slack and Teams, the message has interactive buttons and, where the platform allows it, a modal for the rest.
